+    let out = engine::run(CPS, &lathe_mch(false), &cnc::serialize(&r)).expect("runs");
+    assert!(out.warnings.is_empty(), "{:?}", out.warnings);
+    assert_eq!(g33s(&out.program), vec![("6.825".to_string(), "1.058333".to_string())], "{}", out.program);
